var ul = ASW_ul(source);
var out = [];
var cfg = {};
try { cfg = JSON.parse(String(source.getVariable() || "")) || {}; } catch (e) {}
function push(t, u, s) {
    out.push({ title: String(t), url: u ? String(u) : "", style: { layout_flexGrow: 1, layout_flexBasisPercent: s } });
}
push("🛰 当前站源：" + ASW_host(ul), "", 1);

/* ---- 用户中心（原版：用户◎名◎中心 + 书架 + 阅读记录 + 等级） ---- */
if (cfg.tok) {
    var nick = cfg.user || "已登录";
    var ex = "";
    try {
        var me = JSON.parse(ASW_body(java.get(ul + "/api/v1/users/me", { "Authorization": ASW_bearer(java, cfg.tok) })));
        var u = (me && me.data) ? me.data : {};
        if (u.nickname) nick = u.nickname;
        ex = "Lv." + (u.level || 0) + " 经验" + (u.exp || 0) + (u.vip_level ? (" VIP" + u.vip_level) : "");
    } catch (e2) {
        ex = "登录态可能已过期";
    }
    push("用户◎" + nick + "◎中心", "", 1);
    push("📚 书架", ul + "/api/v1/bookshelf?page={{page}}&page_size=20", 0.45);
    push("🕘 阅读记录", ul + "/api/v1/reading-history?page={{page}}&page_size=20", 0.45);
    if (ex) push(ex, "", 0.45);
} else {
    push("未登录（右上角搜索无需登录，书架/评论需登录）", "", 1);
}

push("--------书库--------", "", 1);

/* ---- 最近更新（原版） ---- */
push("🕒 最近更新", ul + "/api/v1/books?page={{page}}&page_size=20&sort_by=last_chapter_at&sort_order=desc", 0.5);
/* ---- 原创（原版） ---- */
push("✍️ 原创作品", ul + "/api/v1/books?original=1&page={{page}}&page_size=20&sort_by=hot&sort_order=desc", 0.5);

/* ---- 榜单（原版「排行」的动态入口） ---- */
try {
    var bj = JSON.parse(String(java.ajax(ul + "/api/v1/operations/blocks")));
    var bs = bj.data || [];
    var hasRank = false;
    for (var i = 0; i < bs.length; i++) {
        var b = bs[i];
        if (b.placement !== "ranking" || b.kind !== "ranking") continue;
        if (!hasRank) { push("🏆 排行", "", 1); hasRank = true; }
        var p = b.period ? ("&period=" + b.period) : "";
        push("📊 " + b.title, ul + "/api/v1/operations/blocks/" + b.id + "/books?page={{page}}&page_size=20" + p, 0.5);
    }
} catch (e) {
    java.log("ASW榜单失败:" + e);
}

/* ---- 书库排序入口 ---- */
push("📚 书库", "", 1);
var sorts = [["🔥 最热", "hot"], ["👀 人气", "view_count"], ["⭐ 收藏", "favorite_count"], ["📝 字数", "word_count"], ["🆕 最新", "created_at"]];
for (var i = 0; i < sorts.length; i++) {
    push(sorts[i][0], ul + "/api/v1/books?page={{page}}&page_size=20&sort_by=" + sorts[i][1] + "&sort_order=desc", 0.33);
}
push("✅ 完结作品", ul + "/api/v1/books?status=completed&page={{page}}&page_size=20&sort_by=hot&sort_order=desc", 0.5);

/* ---- 分类（原版：跟随登录界面的排序切换） ---- */
var order = "";
var sv = Number(cfg.s || 0);
if (sv === 1) order = "&sort_by=last_chapter_at&sort_order=desc";
else if (sv === 2) order = "&sort_by=view_count&sort_order=desc";
else if (sv === 3) order = "&sort_by=word_count&sort_order=desc";
try {
    var cj = JSON.parse(String(java.ajax(ul + "/api/v1/categories")));
    var cs = cj.data || [];
    if (cs.length) {
        push("🗂 分类" + (["", "（按时间）", "（按人气）", "（按字数）"][sv] || ""), "", 1);
        for (var i = 0; i < cs.length; i++) {
            push("📁 " + cs[i].name, ul + "/api/v1/books?page={{page}}&page_size=20&category_id=" + cs[i].id + order, 0.25);
        }
    }
} catch (e) {
    java.log("ASW分类失败:" + e);
}

/* ---- 自定义标签（原版登录界面输入） ---- */
try {
    var myTags = String(cfg.tags || "").split(/[,，]/);
    var used = 0;
    for (var i = 0; i < myTags.length; i++) {
        var tg = String(myTags[i]).replace(/^\s+|\s+$/g, "");
        if (!tg) continue;
        if (!used) { push("自定义标签🏷️", "", 1); used = 1; }
        push("# " + tg, ul + "/api/v1/books?page={{page}}&page_size=20&tag=" + encodeURIComponent(tg), 0.25);
    }
} catch (e) {}

/* ---- 热门标签 ---- */
try {
    var tj = JSON.parse(String(java.ajax(ul + "/api/v1/search/hot")));
    var ts = tj.data || [];
    if (ts.length) {
        push("🏷 热门标签", "", 1);
        for (var i = 0; i < ts.length && i < 40; i++) {
            push("# " + ts[i], ul + "/api/v1/books?page={{page}}&page_size=20&tag=" + encodeURIComponent(ts[i]), 0.25);
        }
    }
} catch (e) {
    java.log("ASW标签失败:" + e);
}

JSON.stringify(out);

