function ASW_ul(sv) {
    var d = "https://www.alicesw5.homes";
    try {
        var o = JSON.parse(String(sv.getVariable() || ""));
        if (o && o.lines && o.lines.length) {
            var s = String(o.sourl || "");
            for (var i = 0; i < o.lines.length; i++) {
                if (String(o.lines[i].u) === s) return s.replace(/\/+$/, "");
            }
            return String(o.lines[0].u).replace(/\/+$/, "");
        }
        if (o && o.sourl) {
            var v = String(o.sourl).replace(/\/+$/, "");
            /* 旧源遗留的已死主域直接忽略（261128 实测 A 记录超时 + 假 IPv6） */
            if (!/^https?:\/\/(www\.)?alicesw\.com$/i.test(v)) return v;
        }
    } catch (e) {}
    return d;
}

function ASW_host(u) {
    return String(u || "").replace(/^https?:\/\//, "").replace(/[\/?#].*$/, "");
}

function ASW_body(r) {
    try {
        if (r && typeof r.body === "function") return String(r.body());
    } catch (e) {}
    return String(r);
}

function ASW_D(bk) {
    try {
        var o = JSON.parse(String(bk.getVariable("ASW") || "{}"));
        if (o && o.id) return o;
    } catch (e) {}
    return {};
}

function ASW_cover(sv, u) {
    if (!u) return "";
    u = String(u);
    if (/^https?:\/\//.test(u)) return u;
    return ASW_ul(sv) + (u.charAt(0) == "/" ? u : "/" + u);
}

function ASW_lst(j) {
    var a = [];
    try {
        var d = j && j.data ? j.data : (j || {});
        a = d.items || d.books || d.comments || [];
        if (!a.length && d && d.length) a = d;
    } catch (e) {}
    return a;
}

function ASW_tags(t) {
    var r = [];
    try {
        if (!t) return "";
        for (var i = 0; i < t.length; i++) {
            if (typeof t[i] === "string") r.push(t[i]);
            else if (t[i] && t[i].name) r.push(t[i].name);
        }
    } catch (e) {}
    return r.join(",");
}

function ASW_fixJson(s) {
    s = String(s);
    try { return JSON.parse(s); } catch (e) {}
    var k = s.lastIndexOf('{"chapter_no"');
    if (k > 0) {
        try { return JSON.parse(s.substring(0, k).replace(/,\s*$/, "") + "]}"); } catch (e) {}
    }
    return null;
}

function ASW_bearer(jv, tok) {
    /* Rhino: "Bearer " + tok 得到 ConsString，作为 Map<String,String> 的值传进 Java 会抛出
       ClassCastException: ConsString cannot be cast to String；用 strToBytes/bytesToStr 往返强制转成 java.lang.String */
    var s = "Bearer " + tok;
    try { return jv.bytesToStr(jv.strToBytes(s)); } catch (e) { return s; }
}

function ASW_item(b, ul) {
    if (!b) return null;
    var bk = b.book ? b.book : b;
    /* 兼容三种形态：搜索/书库(id,title...) / 书架(book_id,book_title,book_cover_url) / 阅读记录(book_id,book{}) */
    var id = b.book_id ? b.book_id : (bk.id ? bk.id : 0);
    if (!id) return null;
    var title = b.book_title ? b.book_title : bk.title;
    var author = b.book_author ? b.book_author : (bk.author_name || (bk.author && bk.author.pen_name) || bk.original_author || "");
    var cover = b.book_cover_url ? b.book_cover_url : bk.cover_url;
    var syn = b.book_synopsis ? b.book_synopsis : bk.synopsis;
    var cnt = b.chapter_count ? b.chapter_count : bk.chapter_count;
    var wc = b.word_count ? b.word_count : bk.word_count;
    var tgs = bk.tags;
    var cv = cover ? String(cover) : "";
    if (cv && !/^https?:/.test(cv)) cv = ul + (cv.charAt(0) == "/" ? cv : "/" + cv);
    return JSON.stringify({
        "n": String(title || ""),
        "a": String(author || ""),
        "u": ul + "/books/id/" + id,
        "i": cv,
        "s": String(syn || ""),
        "k": ASW_tags(tgs),
        "l": cnt ? ("共" + cnt + "章") : "",
        "w": wc ? String(wc) : ""
    });
}

