var ASW_DEF = {
    sourl: "https://www.alicesw5.homes",
    pub: "https://xn--vcsx64d.asw4.cc/",
    urls: ["https://www.alicesw5.homes", "https://www.alicesw6.homes", "https://www.alicesw7.homes"],
    lines: [
        { u: "https://www.alicesw5.homes", ms: 0 },
        { u: "https://www.alicesw6.homes", ms: 0 },
        { u: "https://www.alicesw7.homes", ms: 0 }
    ],
    s: 0,
    co: 0,
    tags: "",
    tok: "",
    user: ""
};

/* ---------- 基础 ---------- */
function ASW_cfg() {
    var o = null;
    try { o = JSON.parse(String(source.getVariable() || "")); } catch (e) {}
    if (!o || typeof o !== "object") o = {};
    /* 老结构迁移：urls → lines */
    if ((!o.lines || !o.lines.length) && o.urls && o.urls.length) {
        var ls = [];
        for (var i = 0; i < o.urls.length; i++) ls.push({ u: String(o.urls[i]), ms: 0 });
        o.lines = ls;
    }
    if (!o.lines || !o.lines.length) o.lines = JSON.parse(JSON.stringify(ASW_DEF.lines));
    if (!o.sourl) o.sourl = o.lines[0].u;
    if (!o.pub) o.pub = ASW_DEF.pub;
    if (o.s === undefined) o.s = 0;
    if (o.co === undefined) o.co = 0;
    if (o.tags === undefined) o.tags = "";
    if (o.tok === undefined) o.tok = "";
    if (o.user === undefined) o.user = "";
    return o;
}

function ASW_save(o) {
    var a = [];
    for (var i = 0; i < o.lines.length; i++) a.push(o.lines[i].u);
    o.urls = a;
    try { source.setVariable(JSON.stringify(o)); } catch (e) {}
}

function ASW_T(m) {
    try { java.toast(String(m)); } catch (e) {}
}

function ASW_bearer2(tok) {
    var s = "Bearer " + tok;
    try { return java.bytesToStr(java.strToBytes(s)); } catch (e) { return s; }
}

function ASW_rbody(r) {
    try {
        if (r && typeof r.body === "function") return String(r.body());
    } catch (e) {}
    return String(r);
}

function ASW_ph(u) {
    return String(u || "").replace(/^https?:\/\//, "").replace(/[\/?#].*$/, "");
}

function ASW_reload() {
    try { java.reLoginView(); } catch (e) {
        ASW_T("提示：请关闭后重新打开登录界面查看更新");
    }
}

/* ---------- 站源按钮文案（viewName） ---------- */
function ASW_label(i) {
    try {
        var o = ASW_cfg();
        var L = o.lines[i];
        if (!L) return "站源" + (i + 1);
        var ms = (L.ms > 0) ? (L.ms + "ms") : (L.ms < 0 ? "超时" : "");
        var mark = (String(o.sourl) === String(L.u)) ? "✔" : "";
        return mark + "站源" + (i + 1) + " " + ms;
    } catch (e) {
        return "站源" + (i + 1);
    }
}

/* ---------- 发布页解析（三层：base64 跳转 / r('反转') / targetUrl / redirectButton） ---------- */
function ASW_scan(pub0) {
    var lines = [], seenL = {}, queue = [], seenQ = {};
    function norm(u) { return String(u || "").replace(/\s+$/, "").replace(/\/+$/, ""); }
    function isPub(u) { return /asw4\.cc|als1007|alicesw1\.quest/i.test(u); }
    function add(u) {
        u = norm(u);
        if (!u || !/^https?:\/\//.test(u)) return;
        if (/google\.|microsoft\.|firefox\.com|\.txt/i.test(u)) return;
        if (isPub(u)) {
            if (!seenQ[u]) { seenQ[u] = 1; queue.push(u); }
            return;
        }
        if (!/alice|als|asw/i.test(u)) return;
        if (!seenL[u]) { seenL[u] = 1; lines.push(u); }
    }
    function extract(h) {
        var m;
        var r1 = /jump\(['"]([A-Za-z0-9+\/=]+)['"]\)/g;
        while ((m = r1.exec(h))) {
            try { add(java.base64Decode(m[1])); } catch (e) {}
        }
        var r2 = /=\s*r\(['"]([^'"]+)['"]\)/g;
        while ((m = r2.exec(h))) add(String(m[1]).split("").reverse().join(""));
        var r3 = /(?:targetUrl|location(?:\.href)?)\s*=\s*["'](https?:\/\/[^"']+)["']/g;
        while ((m = r3.exec(h))) add(m[1]);
        var r4 = /href=["'](https?:\/\/[^"']+)["']/g;
        while ((m = r4.exec(h))) { if (/alice|als\d|asw/i.test(m[1])) add(m[1]); }
    }
    var start = norm(pub0);
    if (!/^https?:\/\//.test(start)) start = "https://" + start;
    queue.push(start);
    seenQ[start] = 1;
    var rounds = 0;
    while (queue.length && rounds < 8) {
        var u = queue.shift();
        var h = "";
        try { h = String(java.ajax(u)); } catch (e) { h = ""; }
        rounds++;
        if (h) extract(h);
    }
    return lines;
}

function ASW_ping(u) {
    var t0 = Date.now();
    var ok = false;
    try {
        var s = String(java.ajax(u + "/api/v1/config/public"));
        ok = s.indexOf('"data"') > -1 && s.indexOf("Exception") < 0 && s.length > 100;
    } catch (e) { ok = false; }
    return { ok: ok, ms: ok ? (Date.now() - t0) : -1 };
}

/* ---------- 原版：获取站源 ---------- */
function Geturls() {
    var o = ASW_cfg();
    var r = (typeof result !== "undefined" && result) ? result : {};
    var pub = String(r["网址发布页（留空用内置）"] || "").replace(/^\s+|\s+$/g, "") || o.pub || ASW_DEF.pub;
    ASW_T("⏳ 正在读取发布页…（站点改版后需二层跳转，请稍候）");
    var found = [];
    try { found = ASW_scan(pub); } catch (e) { ASW_T("❌ 发布页读取失败：" + e); return; }
    if (!found.length) {
        ASW_T("❌ 获取失败：发布页没有解析到站源\n" + pub);
        return;
    }
    ASW_T("🔎 解析到 " + found.length + " 个候选，正在逐个测速验证…");
    var keep = [], bad = [];
    for (var i = 0; i < found.length && i < 10; i++) {
        var p = ASW_ping(found[i]);
        if (p.ok) keep.push({ u: found[i], ms: p.ms }); else bad.push(found[i]);
    }
    if (!keep.length) {
        ASW_T("❌ 候选站源全部不可用：\n" + found.join("\n"));
        return;
    }
    keep.sort(function (a, b) { return a.ms - b.ms; });
    o.pub = pub;
    o.lines = keep;
