/* ---------- 原版：登录 ---------- */
function Login() {
    var r = (typeof result !== "undefined" && result) ? result : {};
    var o = ASW_cfg();
    var ul = o.sourl;
    var em = String(r["用户名/邮箱"] || "").replace(/^\s+|\s+$/g, "");
    var pw = String(r["密码"] || "");
    if (!em || !pw) { ASW_T("❗ 请先填写用户名/邮箱与密码"); return; }
    ASW_T("⏳ 正在获取图片验证码…");
    var cid = "", img = "";
    try {
        var cj = JSON.parse(ASW_rbody(java.post(ul + "/api/v1/auth/captcha", "{}", { "Content-Type": "application/json" })));
        cid = String(cj.data.captcha_id);
        img = String(cj.data.image);
    } catch (e) {
        ASW_T("❌ 验证码获取失败：" + e);
        return;
    }
    var code = "";
    try { code = String(java.getVerificationCode(img)); } catch (e) { code = ""; }
    if (!code) { ASW_T("已取消登录"); return; }
    ASW_T("⏳ 正在登录…");
    var body = JSON.stringify({ email: em, password: pw, captcha_id: cid, captcha_answer: code });
    var resp = "";
    try {
        resp = ASW_rbody(java.post(ul + "/api/v1/auth/login", body, { "Content-Type": "application/json" }));
    } catch (e2) {
        ASW_T("❌ 登录请求失败（验证码错误或账号密码不对）：" + e2);
        return;
    }
    var tk = "", nm = "";
    try {
        var lj = JSON.parse(resp);
        tk = String(lj.data.tokens.access_token);
        nm = String((lj.data.user && (lj.data.user.nickname || lj.data.user.email)) || em);
    } catch (e3) {}
    if (!tk || tk === "undefined" || tk.length < 20) {
        ASW_T("❌ 登录失败：" + resp.substring(0, 160));
        return;
    }
    o.tok = tk;
    o.user = nm;
    ASW_save(o);
    try { source.putLoginHeader(JSON.stringify({ "Authorization": "Bearer " + tk })); } catch (e4) {}
    ASW_T("✅ 登录成功：" + nm + "\n书架/评论等需要登录的功能已可用");
    try { java.refreshExplore(); } catch (e5) {}
    ASW_reload();
}

