/* ---------- 原版：网络书架 添加/移除 ---------- */
function AFBook(ta) {
    var r = (typeof result !== "undefined" && result) ? result : {};
    var o = ASW_cfg();
    var ul = o.sourl;
    var info = String(r["书籍ID"] || "").replace(/^\s+|\s+$/g, "");
    if (!info) { ASW_T("\n未填入书籍id，请进书籍详情页，或者手动填写。"); return; }
    if (!o.tok) { ASW_T("未登录，请登录后使用"); return; }
    var hd = { "Authorization": ASW_bearer2(o.tok), "Content-Type": "application/json" };
    try {
        var id = info;
        if (!/^\d+$/.test(id)) { ASW_T("书籍ID 必须是数字"); return; }
        /* 若填的是书号，先换成 id */
        var det = null;
        try { det = JSON.parse(String(java.ajax(ul + "/api/v1/books/" + id))); } catch (e0) {}
        if (!det || !det.data || !det.data.id) {
            try {
                var by = JSON.parse(String(java.ajax(ul + "/api/v1/books/by-no/" + id)));
                if (by && by.data && by.data.id) id = String(by.data.id);
            } catch (e1) {}
        }
        var resp = "";
        if (ta) {
            resp = ASW_rbody(java.post(ul + "/api/v1/bookshelf/books/" + id, "{}", hd));
        } else {
            /* Legado 无 java.delete，用 jsoup 发 DELETE */
            var conn = Packages.org.jsoup.Jsoup.connect(ul + "/api/v1/bookshelf/books/" + id);
            conn.method(Packages.org.jsoup.Connection.Method.DELETE);
            conn.header("Authorization", ASW_bearer2(o.tok));
            conn.ignoreContentType(true);
            conn.ignoreHttpErrors(true);
            var res = conn.execute();
            resp = String(res.statusCode()) + "|" + String(res.body());
        }
        var msg = "";
        try { msg = JSON.parse(resp).message || JSON.parse(resp).msg || ""; } catch (e2) { msg = resp.substring(0, 80); }
        ASW_T((ta ? "加入书架：" : "移出书架：") + msg);
    } catch (e3) {
        ASW_T("操作失败：" + String(e3).substring(0, 100) + "\n（可点「跳转」到网页书架操作）");
    }
}

